    @Override // android.app.Activity, android.view.Window.Callback
    public boolean dispatchKeyEvent(KeyEvent keyEvent) {
        int eventKeyCode = keyEvent.getKeyCode();
        if (keyEvent.getAction() == KeyEvent.ACTION_UP
                && eventKeyCode == this.consumedWakeKeyCode) {
            this.consumedWakeKeyCode = -1;
            return true;
        }
        if (keyEvent.getAction() == 0) {
            boolean wasHidden = !this.glanceHudVisible;
            showControlsTemporarily();
            int keyCode = keyEvent.getKeyCode();
            boolean selectKey = keyCode == 23 || keyCode == 109;
            if (wasHidden && (selectKey || isNavigationKey(keyCode))) {
                this.consumedWakeKeyCode = keyCode;
                armSafeDefaultFocus(1400L);
                return true;
            }
            if (selectKey && System.currentTimeMillis() < this.selectGuardUntil) {
                this.consumedWakeKeyCode = keyCode;
                focusSafeDefault();
                return true;
            }
            if (isNavigationKey(keyCode)) {
                long jCurrentTimeMillis = System.currentTimeMillis();
                if (jCurrentTimeMillis - this.lastNavigationAt < 380) {
                    return true;
                }
                this.lastNavigationKeyCode = keyCode;
                this.lastNavigationAt = jCurrentTimeMillis;
            }
            View currentFocus = getCurrentFocus();
            if (currentFocus != this.input && isTextInputKey(keyEvent)) {
                revealInputForEditing();
                if (this.input != null) {
                    this.input.requestFocus();
                    this.input.append(String.valueOf((char) keyEvent.getUnicodeChar()));
                    this.input.setSelection(this.input.getText().length());
                    return true;
                }
            }
            if (currentFocus == this.input) {
                if (keyCode == 20 || keyCode == 22 || keyCode == 61) {
                    hideKeyboard();
                    if (this.voiceButton != null) {
                        this.voiceButton.requestFocus();
                    }
                    return true;
                }
                if (keyCode == 21) {
                    hideKeyboard();
                    if (this.zoomButton != null) {
                        this.zoomButton.requestFocus();
                    }
                    return true;
                }
            }
            if ((keyEvent.isCtrlPressed() && keyCode == 66) || keyCode == 139) {
                sendCurrentText();
                return true;
            }
            if (keyCode == 111 || keyCode == 4 || keyCode == MAX_MAIL_SUMMARY_CHARS || keyCode == 97) {
                emergencyStop("App closed", true, true);
                return true;
            }
            if (handleFocusNavigation(currentFocus, keyCode==KeyEvent.KEYCODE_TAB ? (keyEvent.isShiftPressed()?KeyEvent.KEYCODE_DPAD_LEFT:KeyEvent.KEYCODE_DPAD_RIGHT) : keyCode)) {
                return true;
            }
            if (keyCode == 135 || keyCode == 84) {
                Log.i(TAG, "voice key received code=" + keyCode);
                toggleVoiceRecording();
                return true;
            }
            if ((keyCode == 109 || keyCode == 23) && !(currentFocus instanceof Button)) {
                Log.i(TAG, "voice select key received code=" + keyCode);
                toggleVoiceRecording();
                return true;
            }
            if (keyCode == 134) {
                toggleAmbientMode();
                return true;
            }
            if (keyCode == 138) {
                speakWithRokidChunked("読み上げテストです。Rokidの女性音声で聞こえていますか。");
                return true;
            }
            if (keyCode == 136) {
                speakWithPhoneTts("読み上げテストです。スマホ側のRokid音声で聞こえていますか。");
                return true;
            }
            if (keyCode == 137) {
                playBeepTest();
                return true;
            }
            if (currentFocus != this.input && this.answerScroll != null && (keyCode == 93 || keyCode == 62)) {
                this.answerScroll.smoothScrollBy(0, 220);
                return true;
            }
            if (currentFocus != this.input && this.answerScroll != null && keyCode == 92) {
                this.answerScroll.smoothScrollBy(0, -220);
                return true;
            }
        }
        return super.dispatchKeyEvent(keyEvent);
    }

    @Override // android.app.Activity, android.view.Window.Callback
    public boolean dispatchTouchEvent(MotionEvent motionEvent) {
        if (motionEvent.getAction() == 0) {
            boolean wasHidden = !this.glanceHudVisible;
            showControlsTemporarily();
            if (wasHidden) {
                armSafeDefaultFocus(1400L);
                return true;
            }
        }
        return super.dispatchTouchEvent(motionEvent);
    }

    private void armSafeDefaultFocus(long guardMs) {
        this.selectGuardUntil = Math.max(this.selectGuardUntil,
                System.currentTimeMillis() + guardMs);
        focusSafeDefault();
        this.handler.postDelayed(new Runnable() {
            @Override
            public void run() {
                MainActivity.this.focusSafeDefault();
            }
        }, 120L);
        this.handler.postDelayed(new Runnable() {
            @Override
            public void run() {
                MainActivity.this.focusSafeDefault();
            }
        }, 360L);
    }

    private void focusSafeDefault() {
        if(buttonPanel!=null)for(int i=0;i<buttonPanel.getChildCount();i++){
            View child=buttonPanel.getChildAt(i);
            if(child instanceof Button&&child.isShown()&&child.isEnabled()&&child.isFocusable()&&child.requestFocus())return;
        }
        if(settingsButton!=null&&settingsButton.isShown())settingsButton.requestFocus();
    }

    private boolean handleFocusNavigation(View view, int key) {
        if(!isNavigationKey(key)||buttonPanel==null)return false;
        java.util.ArrayList<View> choices=new java.util.ArrayList<View>();
        for(int i=0;i<buttonPanel.getChildCount();i++){
            View child=buttonPanel.getChildAt(i);
            if(child instanceof Button && child.isShown() && child.isEnabled() && child.isFocusable())choices.add(child);
        }
        if(choices.isEmpty())return false;
        int index=choices.indexOf(view);
        boolean forward=key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_DPAD_DOWN;
        int target=index<0?0:(index+(forward?1:choices.size()-1))%choices.size();
        return requestFocusSafely(choices.get(target));
    }

    private boolean requestFocusSafely(View view) {
        if(view==null||!view.isShown()||!view.isEnabled())return false;
        showControlsTemporarily();
        return view.requestFocus();
    }

    private boolean isNavigationKey(int i) {
        return i == 21 || i == 22 || i == 19 || i == 20;
    }

    private boolean isTextInputKey(KeyEvent event) {
        if (event == null || event.isCtrlPressed() || event.isAltPressed() || event.isMetaPressed()) {
            return false;
        }
        int keyCode = event.getKeyCode();
        if (isNavigationKey(keyCode) || keyCode == 4 || keyCode == 23 || keyCode == 66
                || keyCode == 61 || keyCode == 62 || keyCode == 92 || keyCode == 93
                || keyCode == 111 || keyCode == 134 || keyCode == 135 || keyCode == 136 || keyCode == 137
                || keyCode == 138 || keyCode == 139) {
            return false;
        }
        int unicode = event.getUnicodeChar();
        return unicode >= 32;
    }

    private void revealInputForEditing() {
        if (this.input == null) {
            return;
        }
        this.input.setVisibility(0);
        this.input.setAlpha(1.0f);
        this.handler.removeCallbacks(this.hideInputRunnable);
        this.handler.postDelayed(this.hideInputRunnable, 6500L);
    }

    private void revealInputForText(String text) {
        if (this.input == null) {
            return;
        }
        String value = text == null ? "" : text.trim();
        if (value.length() == 0) {
            hideInputIfIdle();
            return;
        }
        this.input.setVisibility(0);
        this.input.setAlpha(1.0f);
        this.handler.removeCallbacks(this.hideInputRunnable);
        this.handler.postDelayed(this.hideInputRunnable, 9000L);
    }

    private void hideInputIfIdle() {
        if (this.input == null) {
            return;
        }
        String value = this.input.getText() == null ? "" : this.input.getText().toString().trim();
        View currentFocus = getCurrentFocus();
        if (value.length() == 0 && currentFocus != this.input) {
            this.input.setVisibility(8);
        } else if (!this.geminiRequestActive && !this.voiceRecording && currentFocus != this.input) {
            this.input.setVisibility(8);
        }
    }

    private void clearSubmittedInput() {
        if (this.input == null) {
            return;
        }
        this.handler.removeCallbacks(this.hideInputRunnable);
        this.input.setText("");
        this.input.clearFocus();
        this.input.setVisibility(View.GONE);
        hideKeyboard();
    }

    private void scheduleIdleHudCleanup() {
        this.handler.removeCallbacks(this.idleHudCleanupRunnable);
        this.handler.postDelayed(this.idleHudCleanupRunnable, 1000L);
    }

    private void schedulePostIntimacyFollowUp() {
        if (!this.postIntimacySessionActive) {
            return;
        }
        this.postIntimacyFollowUpPending = true;
        this.postIntimacyFollowUpAt = System.currentTimeMillis()
                + POST_INTIMACY_FOLLOW_UP_DELAY_MS;
        this.handler.removeCallbacks(this.postIntimacyFollowUpRunnable);
        this.handler.postDelayed(this.postIntimacyFollowUpRunnable,
                POST_INTIMACY_FOLLOW_UP_DELAY_MS);
        Log.i(TAG, "post-intimacy follow-up scheduled in "
                + POST_INTIMACY_FOLLOW_UP_DELAY_MS + "ms");
    }

    private void markPostIntimacyTurnStarted() {
        this.postIntimacySessionActive = true;
        this.postIntimacyPromptVisible = false;
        this.postIntimacyAftercareStartedAt = 0L;
        this.handler.removeCallbacks(this.postIntimacyReturnToNormalRunnable);
        // This is a fallback for a failed/interrupted response. A successful
        // spoken response reschedules the ten-minute window from its end.
        schedulePostIntimacyFollowUp();
    }

    private void runPostIntimacyFollowUp() {
        if (!this.postIntimacySessionActive || !this.postIntimacyFollowUpPending) {
            return;
        }
        long remaining = this.postIntimacyFollowUpAt - System.currentTimeMillis();
        if (remaining > 0L) {
            this.handler.postDelayed(this.postIntimacyFollowUpRunnable, remaining);
            return;
        }
        if (this.geminiRequestActive || this.voiceRecording || this.morningPlaybackActive
                || this.mascotMode == 2 || (this.proximityStateKnown && !this.glassWorn)) {
            this.handler.postDelayed(this.postIntimacyFollowUpRunnable, 30000L);
            return;
        }
        this.postIntimacyFollowUpPending = false;
        this.postIntimacySessionActive = false;
        this.postIntimacyFollowUpAt = 0L;
        this.postIntimacyAftercareStartedAt = 0L;
        this.postIntimacyPromptVisible = true;
        this.ttsGeneration++;
        this.headGlanceWake = false;
        setGlanceHudVisible(true);
        wakeDisplayForGlance();
        setConversationActive(true);
        setMascotMode(2);
        setMascotSpeechPresentation(true, MASCOT_ACTION_NONE);
        setMascotExpression(MASCOT_EXPR_AFTERGLOW);
        if (this.answer != null) {
            this.answer.setText(POST_INTIMACY_PROMPT);
            scrollAnswerToTop();
        }
        if (this.answerScroll != null) {
            this.answerScroll.setVisibility(View.VISIBLE);
        }
        setStatus("\u8eab\u652f\u5ea6\u306e\u78ba\u8a8d", Color.rgb(90, 220, 120));
        speakWithPhoneTts(POST_INTIMACY_PROMPT, true);
        this.handler.removeCallbacks(this.postIntimacyReturnToNormalRunnable);
        this.handler.postDelayed(this.postIntimacyReturnToNormalRunnable,
                POST_INTIMACY_PROMPT_VISIBLE_MS);
        Log.i(TAG, "post-intimacy follow-up spoken; returning to normal mode");
    }

    private void finishPostIntimacyPrompt() {
        if (!this.postIntimacyPromptVisible) {
            return;
        }
        this.postIntimacyPromptVisible = false;
        this.postIntimacyAftercareStartedAt = 0L;
        setMascotSpeechPresentation(true, MASCOT_ACTION_NONE);
        setMascotExpression(0);
        setMascotMode(0);
        if (this.answer != null && POST_INTIMACY_PROMPT.contentEquals(this.answer.getText())) {
            this.answer.setText("");
        }
        if (this.answerScroll != null) {
            this.answerScroll.setVisibility(View.GONE);
        }
        if (this.status != null) {
            this.status.setVisibility(View.GONE);
        }
        setConversationActive(false);
        if (!this.headTiltActive) {
            setGlanceHudVisible(false);
        }
    }

    private void handlePostIntimacyIncomingPrompt(String prompt) {
        if (!this.postIntimacySessionActive && !this.postIntimacyFollowUpPending
                && !this.postIntimacyPromptVisible) {
            return;
        }
        this.handler.removeCallbacks(this.postIntimacyFollowUpRunnable);
        this.handler.removeCallbacks(this.postIntimacyReturnToNormalRunnable);
        this.postIntimacyFollowUpPending = false;
        this.postIntimacyFollowUpAt = 0L;
        this.postIntimacyPromptVisible = false;
        if (this.postIntimacySessionActive && isPostIntimacyContinuationRequest(prompt)) {
            // Keep the scene state for a short continuation; the response end
            // will restart the full ten-minute window.
            schedulePostIntimacyFollowUp();
            return;
        }
        this.postIntimacySessionActive = false;
        this.postIntimacyAftercareStartedAt = 0L;
        this.ttsGeneration++;
        setMascotSpeechPresentation(true, MASCOT_ACTION_NONE);
        setMascotExpression(0);
        setMascotMode(0);
        Log.i(TAG, "post-intimacy state cleared by a new normal request");
    }

    private void enterPostIntimacyAftercareVisual() {
        if (!this.postIntimacySessionActive) {
            return;
        }
        this.postIntimacyAftercareStartedAt = System.currentTimeMillis();
        setMascotSpeechPresentation(false, MASCOT_ACTION_NONE);
        setMascotExpression(MASCOT_EXPR_POST_INTIMACY_V14_1);
        setMascotMode(0);
        Log.i(TAG, "post-intimacy aftercare visual started");
    }

    private void restoreRecognizedDraft(String text){if(text==null||text.trim().isEmpty())return;String before=input.getText().toString();if(before.trim().isEmpty()){setInputTextVisible(text);return;}new AlertDialog.Builder(this).setTitle("入力中の文章があります").setMessage("現在の入力を認識文で置き換えますか？ 自動送信はしません。").setPositiveButton("置き換える",(d,w)->{if(before.equals(input.getText().toString()))setInputTextVisible(text);else setStatus("入力が変わったため置き換えていません",Color.YELLOW);}).setNegativeButton("戻る",null).show();}

    private void showVoiceTranscript(String text,boolean complete){
        lastVoiceTranscript=text==null?"":text;observationRecognition("VOICE",complete?"RECOGNIZED":"PARTIAL",lastVoiceTranscript);
        if(complete&&!lastVoiceTranscript.isEmpty()){setGlanceHudVisible(true);wakeDisplayForGlance();hudHoldUntil=Math.max(hudHoldUntil,System.currentTimeMillis()+15000L);}
        if(voiceTranscriptView!=null&&!lastVoiceTranscript.isEmpty()){
            voiceTranscriptView.setText((complete?"認識した内容（タップで全文）":"認識途中（未送信）")
                +(voiceCaptureAtLimit?"・録音上限60秒":"")+"\n"+lastVoiceTranscript);
            voiceTranscriptView.setVisibility(View.VISIBLE);
        }
    }

    private void setInputTextVisible(String text) {
        if (this.input == null) {
            return;
        }
        this.input.setText(text == null ? "" : text);
        this.input.setSelection(this.input.getText().length());
        revealInputForText(text);
    }

