    private boolean containsAny(String str, String... keywords) {
        if (str == null || keywords == null) {
            return false;
        }
        for (String keyword : keywords) {
            if (keyword != null && keyword.length() > 0 && str.contains(keyword.toLowerCase(Locale.JAPAN))) {
                return true;
            }
        }
        return false;
    }

