    private String getCustomInstructionsForNormalRequest() {
        String filtered = NormalRequestContextPolicy.custom(stripDormantNazokakeInstructions(getCustomInstructionText()));
        if (filtered.length() == 0) {
            filtered = "あなたはRokidグラス上の私専用の日本語秘書です。回答は必要なことを先に言い、そのあと理由や補足も含めて十分に詳しく答えてください。";
        }
        return "カスタム指示:\n" + filtered;
    }

    private String stripDormantNazokakeInstructions(String raw) {
        if (raw == null || raw.trim().length() == 0) {
            return "";
        }
        String[] segments = raw.replace("\r\n", "\n").replace('\r', '\n')
                .split("(?<=[。！？!?\\n])");
        StringBuilder kept = new StringBuilder();
        int removed = 0;
        for (String segment : segments) {
            String clean = segment == null ? "" : segment.trim();
            if (clean.length() == 0) {
                continue;
            }
            String lower = clean.toLowerCase(Locale.JAPAN);
            boolean riddleSpecific = containsAny(lower,
                    "謎かけ", "なぞかけ", "なぞ掛け", "紺ぶる", "紺ブル",
                    "紺野ぶるま", "芽吹きました", "ロキ、整いました")
                    || (containsAny(lower, "ちんこ", "ち○こ")
                    && containsAny(lower, "お題", "とかけ", "その心", "そのこころ", "掛け"));
            if (riddleSpecific) {
                removed++;
                continue;
            }
            if (kept.length() > 0) {
                kept.append('\n');
            }
            kept.append(clean);
        }
        if (removed > 0) {
            Log.i(TAG, "normal prompt isolated from dormant nazokake instructions segments="
                    + removed);
        }
        return kept.toString().trim();
    }

    /* JADX INFO: Access modifiers changed from: private */
    public String applyCustomInstructionFromText(String str) {
        String strTrim = str == null ? "" : str.trim();
        if (strTrim.length() == 0) {
            return null;
        }
        // Dynamic memory requests must reach Gemini's tools. Only explicit
        // customization requests may mutate custom_instructions here.
        if (!(strTrim.contains("カスタム指示") || strTrim.contains("指示に追加"))) {
            return null;
        }
        if (strTrim.contains("削除") || strTrim.contains("消して") || strTrim.contains("クリア")) {
            getPreferences().edit().putString(KEY_CUSTOM_INSTRUCTIONS, "").apply();
            pushCustomInstructionsToPhoneAsync();
            return "カスタム指示を削除しました。";
        }
        if (!strTrim.contains("追加") && !strTrim.contains("覚えて") && !strTrim.contains("記憶して")) {
            return null;
        }
        String strTrim2 = getPreferences().getString(KEY_CUSTOM_INSTRUCTIONS, "").trim();
        String strTrim3 = strTrim.replace("カスタム指示に", "").replace("カスタム指示へ", "").replace("追加して", "").replace("追加", "").replace("覚えて", "").replace("記憶して", "").trim();
        if (strTrim3.length() == 0) {
            return null;
        }
        String mergedInstructions = strTrim2.length() == 0 ? strTrim3 : strTrim2 + "\n" + strTrim3;
        if (mergedInstructions.length() > MAX_CUSTOM_CHARS) {
            return "カスタム指示は最大" + MAX_CUSTOM_CHARS + "文字です。現在"
                    + strTrim2.length() + "文字あるため、スマホの編集画面で整理してから追加してください。";
        }
        getPreferences().edit().putString(KEY_CUSTOM_INSTRUCTIONS, mergedInstructions).apply();
        pushCustomInstructionsToPhoneAsync();
        return "カスタム指示に追加しました。\n" + strTrim3;
    }

