        return (int) ((calendarFor(calendar2.get(1), calendar2.get(2) + 1, calendar2.get(5)).getTimeInMillis() - calendarFor(calendar.get(1), calendar.get(2) + 1, calendar.get(5)).getTimeInMillis()) / 86400000);
